<?php
require_once __DIR__.'/../includes/functions.php';require_role('admin');verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$q=db()->prepare('INSERT INTO subjects(subject_name,subject_code,credit_hours) VALUES(?,?,?)');$q->execute([trim($_POST['subject_name']),trim($_POST['subject_code']),(int)$_POST['credit_hours']]);audit('Created subject',null,$_POST['subject_code']);flash('success','Subject added.');}catch(Throwable $e){flash('danger','Unable to add subject. Check for duplicate subject code.');}redirect('subjects.php');}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete_subject'])){verify_csrf();db()->prepare('DELETE FROM subjects WHERE subject_id=?')->execute([(int)$_POST['delete_subject']]);audit('Deleted subject');flash('success','Subject deleted.');redirect('subjects.php');}
$rows=db()->query('SELECT * FROM subjects ORDER BY subject_name')->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="row g-3"><div class="col-md-4"><div class="card"><div class="card-header">Add subject</div><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-2"><label class="form-label">Subject name</label><input class="form-control" name="subject_name" required></div><div class="mb-2"><label class="form-label">Subject code</label><input class="form-control" name="subject_code" required></div><div class="mb-3"><label class="form-label">Credit hours</label><input class="form-control" type="number" name="credit_hours" min="1" max="6" value="3" required></div><button class="btn btn-primary">Add subject</button></form></div></div></div><div class="col-md-8"><div class="card"><div class="card-header">Subject catalogue</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Subject</th><th>Code</th><th>Credits</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['subject_name'])?></td><td><?=e($r['subject_code'])?></td><td><?=e((string)$r['credit_hours'])?></td><td><form method="post" class="d-inline"><?=csrf_field()?><button class="btn btn-sm btn-outline-danger" name="delete_subject" value="<?=$r['subject_id']?>" data-confirm="Delete subject?">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php include __DIR__.'/../includes/footer.php';?>